#!/usr/bin/env python
"""Generate docs/looker_studio/field_definitions.md from the REAL tables (column names + types) and bi.FIELD_DOC."""
import sys
from pathlib import Path
ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "src"))
from growthpulse import bi, warehouse

con = warehouse.connect(read_only=True)
L = ["# BI data model and field definitions (auto-generated)\n",
     "_Generated by `python scripts/build_bi_docs.py` from the actual tables. All data are **SYNTHETIC**._\n",
     "**Where the tables live.** BigQuery mode: dbt builds `<dataset>_reporting` (`rpt_*`); Python publishes `<dataset>_analytics` (`bi_*`). "
     "Local mode: DuckDB schemas `gp_reporting` / `gp_bi`, and identical CSVs in `dashboard/bi_exports/`.\n",
     "**Looker Studio rules of thumb.** Metrics are SUMs. Build ratios as calculated fields `SUM(a)/SUM(b)` (never average a ratio). "
     "Use `*_eligible_*` columns for ROAS / LTV / CAC-by-cohort so recent cohorts do not distort results.\n",
     "| Table | Dataset | Grain | Report pages | Date field | Rows |", "|---|---|---|---|---|---:|"]
for r in bi.REGISTRY:
    n = con.sql(f"select count(*) from {bi.local_ref(r['name'])}").fetchone()[0]
    L.append(f"| `{r['name']}` | `<dataset>_{r['layer']}` | {r['grain']} | {r['pages']} | {r['date_field'] or '-'} | {n:,} |")
L.append("")
for r in bi.REGISTRY:
    cols = con.sql(f"describe {bi.local_ref(r['name'])}").df()
    L += [f"## `{r['name']}`", f"**Grain:** {r['grain']}  \n**Used on:** {r['pages']}  \n**Looker Studio date dimension:** `{r['date_field'] or 'none'}`\n",
          "| Field | Type | Looker Studio type | Definition |", "|---|---|---|---|"]
    for _, c in cols.iterrows():
        t = str(c.column_type)
        ls = ("Date" if t == "DATE" else "Date & Time" if t.startswith("TIMESTAMP") else "Number" if any(k in t for k in ("INT", "DOUBLE", "DECIMAL", "FLOAT")) else "Boolean" if t == "BOOLEAN" else "Text")
        L.append(f"| `{c.column_name}` | {t} | {ls} | {bi.FIELD_DOC.get(c.column_name, '')} |")
    L.append("")
out = ROOT / "docs" / "looker_studio" / "field_definitions.md"
out.parent.mkdir(parents=True, exist_ok=True)
out.write_text("\n".join(L))
print("wrote", out)
